=if(C3="","",
let(template_vol,
iferror(if(
F3="Whole-plasmid",V3,
if(left(C3)="d",
 ifs(
   FALSE,"Quintara Biosciences requests about 10 ng per kb of PCR amplicon",
   FALSE,"Genewiz/Azenta specifies the scaling below, which is more conservative",
   AZ3>6,80,AZ3>4,50,AZ3>2,6,AZ3>1,4,AZ3>0.5,2,TRUE,1)*V3,
 settings_SequencingSangerPlasmidTargetng)
 / if(U3="",settings_SequencingSangerPlasmidDefaultConc,U3)),""),
primer_vol,if(F3="Sanger",settings_SequencingPrimerVolume,""),
{"Calculated:",
if(template_vol>V3-primer_vol,V3-primer_vol,template_vol),
primer_vol}
))
